template <class S> concept ExprAlg = requires(S s, int i) {
    typename S::template repr<int>;
    { s.lit(i) } -> std::same_as<typename S::template repr<int>>;
};
struct Eval  { template <class T> using repr = T; int lit(int i) const { return i; }
               int add(int a, int b) const { return a + b; } };
struct Print { template <class T> using repr = std::string;
               std::string lit(int i) const { return std::to_string(i); }
               std::string add(std::string a, std::string b) const { return "(" + a + " + " + b + ")"; } };
template <ExprAlg S> auto exp(const S& s) { return s.add(s.lit(2), s.lit(3)); }  // exp(Eval{})=5

