template <template <class> class F> struct Program {
    static typename F<int>::repr exp() {
        using R = typename F<int>::repr;
        return F<int>::add(F<int>::lit(2), F<int>::lit(3));
    }
};
template <class T> struct Eval { using repr = T;
    static repr lit(int i) { return i; }
    static repr add(repr a, repr b) { return a + b; } };
